26	        String detail = e.getBindingResult().getFieldErrors().stream()
27	                .map(fe -> fe.getField() + " " + fe.getDefaultMessage())
28	                .findFirst()
29	                .orElse("请求参数不合法");
30	        return ResponseEntity.badRequest()
31	                .body(new ErrorResponse(HttpStatus.BAD_REQUEST.name(), detail));
