70	        String coolingRequestId = newRequestId();
71	        assertEquals(200, cooling(id, coolingRequestId, T0.plusHours(14))
72	                .getResponse().getStatus());
73	        MvcResult coolingConflict = cooling(id, coolingRequestId, T0.plusHours(16));
74	        assertEquals(409, coolingConflict.getResponse().getStatus(),
75	                "降温指令同键异参应返回 409");
76	        JsonNode batch = json(mockMvc.perform(
