168	                        req.recoveredAt(), req.viabilityPercent(), req.contaminated(), qualified,
169	                        generationAfter, statusAfter, LocalDateTime.now(clock));
170	            } catch (DuplicateKeyException e) {
171	                // 并发回收同批次：唯一约束兜底，失败批次也只能回收一次
172	                throw ApiException.unprocessable("该批次已受理过回收，每批次仅允许回收一次");
