205	    private void assertPitchable(YeastUnit unit, int expectedVersion, LocalDateTime startedAt) {
206	        if (unit.version() != expectedVersion) {
207	            throw ApiException.conflict(
208	                    "酵母单元版本已变更：期望 " + expectedVersion + "，实际 " + unit.version());
209	        }
210	        if (unit.status() == YeastStatus.SCRAPPED) {
