215	                    "酵母单元已被批次 " + unit.occupiedByBatchId() + " 占用，一单元仅供一个主酵批次");
216	        }
217	        if (unit.generation() > MAX_PITCH_GENERATION) {
218	            throw ApiException.unprocessable(
219	                    "酵母单元代次 " + unit.generation() + " 已达限，代次 6 不能启动新主酵");
220	        }
221	        if (unit.lastRecoveredAt() != null) {
