231	    private StoredResponse idempotent(String requestId, String endpoint, String fingerprint,
232	                                      Supplier<StoredResponse> action) {
233	        try {
234	            return idempotencyService.execute(requestId, endpoint, fingerprint, action);
235	        } catch (ConcurrentReplayException e) {
236	            // 并发同键：回滚本次业务写入，按首次受理结果裁决
237	            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
238	            return idempotencyService.resolveConcurrent(e.requestId(), e.fingerprint());
239	        }
240	    }
