259	     */
260	    private String structured(Object... fields) {
261	        try {
262	            return objectMapper.writeValueAsString(List.of(fields));
263	        } catch (JsonProcessingException e) {
264	            throw new IllegalStateException("请求指纹序列化失败", e);
265	        }
266	    }
