    }

    @Test
    @DisplayName("容量调整：成功版本加 1；旧版 409；缩到已接收量以下 422")
    void capacityUpdateRules() throws Exception {
        JsonNode tank = registerReceivingTank(newRequestId(), "RT-CAP", "100");
