        long[] s = twoJudgedSources("B-CAP-A", "B-CAP-B");
        registerSourceLiquor(s[0], newRequestId(), "20");
        registerSourceLiquor(s[1], newRequestId(), "30");
        assertEquals(201, mergeReceive(newRequestId(), "RT-CAP", List.of(s[0], s[1]), 3, RECEIVED_AT)
