                "胜方搭配源被核销，败方搭配源必须保持未核销");
        BigDecimal received = jdbc.queryForObject(
                "SELECT received_liters FROM receiving_tank WHERE tank_code='RT-RACE-SRC'",
                BigDecimal.class);
        assertEquals(0, new BigDecimal("20.000").compareTo(received), "仅胜方 20 升入罐");
    }
}
